#include <stdio.h>
#include <limits.h>

static int is_whitespace(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r';
}

int main(void) {
    long lines = 0;
    long words = 0;
    long bytes = 0;
    int in_word = 0;
    long cur_line = 0;
    long maxlen = 0;
    int c;

    while ((c = fgetc(stdin)) != EOF) {
        unsigned char uc = (unsigned char)c;
        long line_byte_count;

        bytes++;

        if (uc == '\n') {
            lines++;
            cur_line = 0;
        } else {
            line_byte_count++;
        }

        if (is_whitespace(uc)) {
            in_word = 0;
        } else {
            if (!in_word) {
                words++;
                in_word = 1;
            }
        }

        maxlen = (line_byte_count > maxlen) ? line_byte_count : maxlen;
    }

    /* Handle last line without trailing newline: always counts as a line.
       We've already incremented cur_line for each of its bytes, so we need to add it only when max_line_len > 0. */

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);

    return 0;
}
EOF
